#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int a, b;
    long long l, r;
    cin >> a >> b >> l >> r;

    if (r - l + 1 >= 2LL * (a + b)) {
        cout << (a <= b ? a + 1 : 2 * a - b) << "\n";
        return 0;
    }

    string pattern;
    for (int i = 0; i < a; i++) {
        pattern += ('a' + i);
    }

    l--;
    r--;

    std::set<int> usedSet;
    int minDistinctCount = 26;

    for (int firstCharIdx = 0; firstCharIdx < 26; firstCharIdx++) {
        for (int secondCharIdx = a; secondCharIdx < 26; secondCharIdx++) {
            std::string currentStr = pattern;
            for (int i = 0; i < b; i++) {
                currentStr += ('a' + firstCharIdx);
            }
            usedSet.clear();

            std::string lastAChars = currentStr.substr((int)currentStr.size() - a);
            for (char c : lastAChars) {
                usedSet.insert(c - 'a');
            }

            int nextCharCode = 0;
            for (int i = 0; i < a; i++) {
                while (usedSet.count(nextCharCode)) {
                    nextCharCode++;
                }
                currentStr += ('a' + nextCharCode);
                nextCharCode++;
            }

            for (int i = 0; i < b; i++) {
                currentStr += ('a' + secondCharIdx);
            }

            int length = (int)currentStr.size();
            usedSet.clear();

            for (int i = (int)(l % length); i != (int)((r + 1) % length); i = (i + 1) % length) {
                usedSet.insert(currentStr[i] - 'a');
            }
            if ((int)usedSet.size() < minDistinctCount) {
                minDistinctCount = (int)usedSet.size();
            }
        }
    }
    cout << minDistinctCount << "\n";

    return 0;
}
